(() => {
  'use strict';
  const D=window.SARAVOIA,main=document.querySelector('main'),dialog=document.querySelector('dialog');
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const all=[...D.places,...D.people,...D.timeline,...D.extra];
  const record=t=>D.extra.find(r=>r.title===t);
  const sourceButton=r=>`<button class="text-button" data-record="${esc(r.id)}">Read record</button>`;
  const head=(k,t,p)=>`<section class="page-head"><a class="back" href="#home">County archive</a><p class="eyebrow">${k}</p><h1>${t}</h1><p class="lead">${p}</p></section>`;
  const section=(title,body)=>`<section class="container reveal"><div class="section-heading"><h2>${title}</h2></div>${body}</section>`;
  const cards=rs=>`<div class="card-grid">${rs.map(r=>`<article class="card"><p class="eyebrow">${esc(r.kicker)}</p><h3>${esc(r.name)}</h3><p>${esc(r.summary)}</p>${sourceButton(r)}</article>`).join('')}</div>`;
  const streets=[['Bauble Terrace','Wide single-story houses, flat roofs and some rooftop garden decks border a gently rising road.'],['Rosethorn Boulevard','White and pink roses grow in dense manicured bushes beside precisely detailed houses.'],['Fluvial Court','Smoothed cobblestones and somewhat taller, broader houses distinguish the road.'],['Ashbeast Park','Large shade trees form a canopy above humble cottages; one captured interior uses basalt brick and red-hued timber.']];
  const home=()=>`<section class="hero"><img src="assets/witchtown.jpg.png" alt="Illustrated open black-iron Witchtown gate with gold vines, apple trees, roses, cobbled paths and varied houses" fetchpriority="high"><div class="hero-content"><div><p class="eyebrow">The County of Saravoia</p><h1>Through the<br>Witchtown gates.</h1><p>Places, people and the written record of Saravoia,<br>beginning in its residential quarter.</p><p class="image-caption">Witchtown · an artistic interpretation of the recorded descriptions.</p></div><a class="button gold" href="#witchtown">Enter Witchtown</a></div></section><section class="container"><div class="intro-row"><div><p class="eyebrow">Explore the County</p><h2>Six paths into<br>the archive.</h2></div><p>Walk through its places, trace its history, and read the records behind its language, craft and civic life.</p></div><div class="directory">${[['places','Places','Gates, streets, towers and the palace.'],['people','People','Saravyn names, offices and recorded roles.'],['history','History','From the first idea to settlement and civic life.'],['language','Language','Names, attested phrases and the Saravic record.'],['craft','Craft & material','Architecture, objects, heraldry and trade.'],['records','Records','The Chronicle, County documents and research library.']].map(([route,title,text],i)=>`<a href="#${route}"><span class="number">0${i+1}</span><h3>${title}</h3><p>${text}</p></a>`).join('')}</div></section><section class="dark-section"><div class="container two-col"><div><p class="eyebrow">From the County record</p><h2>A settlement.<br>A fortified approach.<br>A written history.</h2></div><div><p>The Saravoia Chronicle records the beginning of Cabotsaria, the construction of the Witchfort, the County’s political history and the opening of adventurer settlement.</p><a href="#history">Read the chronology</a></div></div></section>`;
  const witchtown=()=>head('Places / residential quarter','Witchtown','Black iron, gold vines, apple trees and roses. A public square opens onto the four roads of the residential quarter.')+`<section class="container"><div class="wide-feature"><img src="assets/witchtown.jpg.png" alt="Artistic rendering of Witchtown’s entrance and connected neighbourhood"><div class="feature-copy"><p class="eyebrow">The open gate</p><h2>Iron and gold.<br>Gardens and streets.</h2><p>The houses are modest, well maintained and painted in varied colours. Most are one story.</p>${sourceButton(D.places[0])}</div></div><div class="section-heading"><h2>The four residential roads</h2><small>Meeting at Cauldron Fret</small></div><div class="street-list">${streets.map(([name,p])=>`<article class="street"><h3>${name}</h3><p>${p}</p></article>`).join('')}</div><div class="two-col"><div><h2>Cauldron Fret</h2><p>Rows of small houses in different construction styles stand along the roads crossing here.</p>${sourceButton(D.places[1])}</div><div><h3>Documented room numbers</h3><p>Witchtown: <strong>68632</strong><br>Cauldron Fret: <strong>68939</strong></p><details><summary>A note on street directions</summary><p>The room signs and recorded traversal place Fluvial Court west and Ashbeast Park south. The help scroll gives the reverse. This archive retains both accounts while a ruling is pending.</p></details></div></div><p class="note">The illustration combines recorded features with artistic choices. Its distant water, bridge, lighting and complete street arrangement do not establish County geography.</p><a class="button" href="#places">Explore more places</a></section>`;
  const places=()=>head('Places','The places of Saravoia','Each place has its own function, materials and recorded character.')+section('Gates, courts and streets',cards(D.places))+section('Names for the expanding place index',`<p>Tor'Ancyrion · Tor'Nocturna · Tor'Vitrae · Tor'Qamad · Chantry Temyrkr · Lienas'niena · Nedhvala Visindi · Atrabalan'Ylnova</p><p class="note">These names are supplied by the handoff brief. Individual descriptions and their relationships will be added as their source records are incorporated.</p>`);
  const people=()=>head('People','Names in the County record','Recorded offices, civic roles and the people named in Saravoia’s sources.')+section('People & offices',cards(D.people))+section('Titles and belonging',`<div class="two-col"><article><h3>Saravyn, Vynlada and Vynren</h3><p>The Chronicle records grants of Vynlada to Kirsi and Vynren to Gaelyn. Their full definitions and precedence are not supplied by the captured passage.</p>${sourceButton(record('Vynlada / Vynren / Saravyn'))}</article><article><h3>Vaiquin and Vaiquinar</h3><p>Both forms occur in the records, alongside “The Vaiquinar.” Their relationship remains a question for the terminology record.</p>${sourceButton(record('The Vaiquinar / Vaiquin / Vaiquinar'))}</article></div><p class="note">Titles are presented as dated attestations. Clothing observed during one encounter does not define a permanent character appearance.</p>`);
  const highlights=[['7 Lupar 985AF','The Big Idea','The opening entry in Nezaya’s Chronicle.'],['10 Ero 986AF','County established','Land acquisition and Cabotsaria construction have their own earlier entries.'],['24 Mayan 987AF','The Witchfort milestone','One of the recorded construction milestones.'],['17 Sarapin 988 AF','Saravyn titles and oaths','Kirsi, Gaelyn and Nezaya are named in the entry.'],['11 Miraman 989AF','Code of Sarave, vol I','The Chronicle records publication and refers to SARAVOIA 2.'],['2 Sarapin 992AF','The Aster Malik contract','The Chronicle records Saravoia becoming a vassal of Aster Malik.'],['20 Scarlatan 993AF','Attack on the Witchfort','The County account places the beginning of the Saravyn-Chaghut War here.'],['20 Aeguary 994AF','The Visindi Collection','The collection opens, with a curator sought.'],['6 Scarlatan 996 AF','Recognition by Vastar','The Chronicle reports recognition and protection through Aster Malik.'],['18 Valnuary 996AF','Adventurer settlement','Neugierig Stormsong is named as the first settler in the new opening.']];
  const history=()=>head('History','The Saravoia Chronicle','An authored County account, preserving the dates and documentary references as recorded.')+section('Milestones',`<p class="year-note">Dates below use the Achaean AF calendar. Statements are attributed to Nezaya’s Chronicle.</p><div class="timeline">${highlights.map(([date,title,text])=>{const r=D.timeline.find(x=>x.title===date);return `<article class="timeline-entry"><time>${date}</time><h3>${title}</h3><p>${text}</p>${sourceButton(r)}</article>`}).join('')}</div><details><summary>The war’s end: differing dates</summary><p>The Chronicle places yielding and the formal end in 994 AF. The enemy scroll calls the war 993–995 AF, and a letter dated 21 Ero 995 says it has ended “for now.” The archive preserves these accounts separately.</p></details><details><summary>Divine and civic references</summary><p>The Chronicle names Scarlatti at Gaelyn’s appointment, Vastar in the recognition of Saravoia, and the Order of the Sky and Emissary of Whiirh at the Aster Town shrine event. These dated references do not establish a uniform County religion.</p></details>`)+section('The captured chronology',`<div class="records-list">${D.timeline.map(r=>`<details><summary>${esc(r.title)}</summary><p>${esc(r.text)}</p>${sourceButton(r)}</details>`).join('')}</div><p class="note">References within the Chronicle are preserved as reading leads. Their original PUBLIC, MEROPIS, EVENTS and SARAVOIA posts are separate sources.</p>`);
  const language=()=>head('Language','Names and spoken forms','Preserving exact terminology, attested phrases and the distinction between recorded and constructed vocabulary.')+section('Saravic',`<div class="two-col"><div><h2>The ceremonial language</h2><p>The supplied handoff describes Saravic as the ceremonial language of Saravoia and a Tsol-based dialect specific to the County.</p>${sourceButton(record('Saravic'))}</div><div><p>The language record will keep direct Saravic, attested Tsol and Karthic, shared forms and constructed vocabulary distinct. Translations will accompany their own sources.</p></div></div><div class="scroll-table"><table class="term-table"><thead><tr><th>Attested form</th><th>Recorded use</th><th>Record</th></tr></thead><tbody><tr><td>Asa-thi lienakhar</td><td>Repeated in Nezaya’s writing. Its position suggests an address or greeting; no translation is supplied by these passages.</td><td>${sourceButton(record('Asa-thi lienakhar'))}</td></tr><tr><td>Chaire Trisagia!</td><td>A closing formula in public joust results. Translation is not supplied.</td><td>${sourceButton(record('Chaire Trisagia!'))}</td></tr></tbody></table></div><div class="language-note"><h2>The word and its source stay together.</h2><p>A proposed word remains proposed. A constructed lexicon remains constructed until adoption is recorded. Spelling variants are retained rather than silently corrected.</p></div><h3>Names requiring a terminology ruling</h3><p>Vaiquin / Vaiquinar · Bauble Terrace / Terrance · Ashbeast / Ashbeat · Ruganala / Rugalana · Atralazari / Atralanzari</p>`);
  const craft=()=>head('Craft & material','Materials, marks and making','Architecture, furnishing, heraldry and practical craft in the County record.')+section('A palette with local differences',`<div class="swatches" aria-label="Heraldic red, gold, black, pale stone and wood colours"><span style="background:#8c2637" title="Red"></span><span style="background:#c89f4b" title="Gold"></span><span style="background:#242024" title="Black"></span><span style="background:#e3ddd0" title="Pale granite"></span><span style="background:#784b39" title="Timber"></span></div><div class="material-groups"><article class="material-group"><h3>The fortified approach</h3><p>Blackened iron and metal, crystal-fragment finishes, steel, granite, cold iron and tempered glass.</p></article><article class="material-group"><h3>The Tetra and towers</h3><p>White granite, black brick and copper treatments are described in these particular spaces.</p></article><article class="material-group"><h3>Residential construction</h3><p>Painted walls, polished hardwood, basalt brick, red-hued timber and paned windows appear in captured houses.</p></article><article class="material-group"><h3>The wider craft direction</h3><p>The handoff adds cedar, mahogany, ruby, restrained amethyst and specified marble finishes, with a contextual preference for gold in high design.</p>${sourceButton(record('Handoff material direction'))}</article></div>`)+section('Heraldry & maker marks',`<div class="two-col"><div><p class="eyebrow">Arms supplied by the handoff</p><h2>Gules,<br>a bat displayed Or.</h2><p>A red field bearing a gold displayed bat. The official specification and decorative interpretations are separate records.</p>${sourceButton(record('Gules, a bat displayed Or.'))}</div><div><h3>Keep attribution precise</h3><p>County arms, personal arms and maker marks are distinct. A motif on a door is not automatically an official emblem. New heraldic treatments will be kept separate from the recorded arms.</p></div></div>`)+section('Craft, trade and collections',`<div class="card-grid">${['CLHELP SAMPLES / Saravyn Sample Scouting, for you carpenters.','The Visindi Collection','Moonlit Menagerie of Art'].map((t,i)=>{const r=record(t);return `<article class="card"><p class="eyebrow">${['Materials','Collection','Art event'][i]}</p><h3>${['Sample scouting','The Visindi Collection','Moonlit Menagerie'][i]}</h3><p>${['The County notice credits Ticca’s recording of sample locations and announces CLHELP SAMPLES.','The Chronicle records its opening in 994 AF. Individual works will be added with their own sources.','Public notices identify Gallus Blackwing as host; the event record does not supply a catalogue of County artworks.'][i]}</p>${sourceButton(r)}</article>`}).join('')}</div>`)+section('The Saravyn Navy',`<p>The Navy scroll is dated 997 AF. It records three vessels, their equipment and their intended use.</p><div class="card-grid">${[['SNS Shadow Witch','War Galley','The Countess’s flagship; three ballistae, two onagers and an Arcanian arm.'],['SNS Auric Lance','Seastrider','A vessel for hunting, trade and voyaging, equipped with a Large Cartographer’s Desk.'],['SNS Scarlet Dancer','Windcutter','A patrol and travel vessel armed with an Arcanian arm.']].map(([t,k,p])=>`<article class="card"><p class="eyebrow">${k}</p><h3>${t}</h3><p>${p}</p>${sourceButton(record(t))}</article>`).join('')}</div><p class="note">These are the fleet details at the time of the scroll; current condition and permissions need their own current records.</p>`);
  const records=()=>head('Records','The written archive','County documents and a research bibliography, with source type and reading status kept visible.')+section('Saravoian records',`<div class="card-grid">${[['Saravoia Chronicle','Chronicle','The captured County chronology, composed by Nezaya.'],['Code of Sarave, vol I','Legal record','Publication is recorded in the Chronicle; the full text is still to be incorporated.'],['Travel Guide / CLHELP TRAVELGUIDE / CLTHELP TRAVELGUIDE / LANDMARKS','Travel Guide','The earlier summary supplies useful leads; the primary passage awaits retrieval.'],['Saravyn Oaths / Vynlada Oaths / Oath of Office','Oaths and offices','The Chronicle refers to records retained in the palace vault.'],['Saravyn Navy / SNS','Navy scroll','Vessels, flag rules, permissions and engagement policy in the dated County document.'],['1018 Asterian Festival','Public planning','Public notices include Saravoia and Neugierig in a tentative festival schedule.']].map(([t,k,p])=>`<article class="card"><p class="eyebrow">${k}</p><h3>${k==='Chronicle'?'Saravoia Chronicle':k}</h3><p>${p}</p>${sourceButton(record(t))}</article>`).join('')}</div>`)+section('Research library',`<p>Visible catalogue titles and attributions are preserved below. A listed book is a reading lead; its contents are not inferred from its title. Truncated titles remain as captured.</p><div class="filter-bar" aria-label="Bibliography views"><button data-books="associated" aria-pressed="true">Visindi & Moliuvia</button><button data-books="context" aria-pressed="false">Contextual reading</button><button data-books="all" aria-pressed="false">Full catalogue · ${D.books.length}</button></div><div id="book-list" class="records-list"></div>`);
  const about=()=>head('The archive','A record that can grow.','A place for the County’s descriptions and documents, alongside clearly identified visual interpretation.')+section('How material is recorded',`<div class="two-col"><div><h3>Documentary layers</h3><p>Room descriptions, County help, Chronicle entries, books, public news and constructed vocabulary retain their own sources and dates. Conflicting spellings and accounts are kept for review.</p></div><div><h3>Visual references</h3><p>The Witchtown image is an artistic interpretation. Its documented gate, gardens and residential features are distinguished from the composition and incidental background.</p></div></div><details><summary>Source register</summary>${D.sources.map(s=>`<p><strong>${esc(s.id)}</strong> · ${esc(s.name)}<br>${esc(s.kind)}</p>`).join('')}<p>The earlier Travel Guide assistant summary is treated as a secondary retrieval lead, not an inspected primary document.</p></details><details><summary>Contributions and corrections</summary><p>The handoff designates Nezaya as the reviewer for Saravoia additions and corrections. Her preferred public process and title wording are still being confirmed. Technical corrections can be handled separately.</p></details><p class="note">Working edition · ${D.updated}. The content framework is ready to receive reviewed additions.</p>`);
  const countyHome=()=>`<section class="county-hero"><div class="county-intro"><p class="eyebrow">The County Archive</p><h1>Saravoia</h1><p class="county-subtitle">Settlements, fortifications,<br>courts and the written record.</p><a class="button gold" href="#places">Explore the County</a></div><div class="county-destinations"><p class="eyebrow">Places within the wider County</p>${[D.places[8],D.places[2],D.places[3],D.places[0],D.places[9]].map(r=>`<button data-record="${esc(r.id)}"><span>${esc(r.name)}</span><small>${esc(r.kicker)}</small></button>`).join('')}</div></section>`+home().slice(home().indexOf('<section class="container">'));
  const landing=()=>`<section class="reference-opening rendered-opening" aria-label="Saravoia castle entrance"><img src="assets/saravoia-black-keep-v3.png" alt="Gothic stained-glass panels frame a formal stone courtyard overlooking an enormous black fortified keep on a broad rocky hilltop and villages across sparse foothills" fetchpriority="high"><span class="landing-bat" aria-hidden="true"><img src="assets/flying-bat.svg" alt=""></span><a class="corner-crest" href="#county" aria-label="County Palatinate of Saravoia"><img src="assets/decorative-bat.png" alt="Gold and crimson decorative bat crest"><img class="crest-wordmark" src="assets/county-palatinate-wordmark.png" alt="County Palatinate of Saravoia"></a><div class="rendered-title"><h1 class="sr-only">County Palatinate of Saravoia</h1><p>People · Places · Craft · History · Lore</p><a class="button gold" href="#county">Enter Saravoia</a></div></section><div class="entrance-caption"><p>Opening artwork · the wider County of Saravoia.</p><a class="button gold mobile-enter" href="#county">Enter Saravoia</a></div><section class="container"><div class="intro-row"><div><p class="eyebrow">Beyond the gates</p><h2>The keep.<br>The villages.<br>The County.</h2></div><div><p>A gothic keep above the Sarave Foothills, villages across the hills, and a County of places and written records to explore.</p><a class="text-button" href="#county">Explore the County archive</a></div></div><div class="directory">${[['places','Places','Settlements, fortified approaches, towers and courts.'],['people','People','Saravyn names, offices and recorded roles.'],['history','History','County chronology and the references behind it.'],['language','Language','Saravic, attested forms and terminology.'],['craft','Craft & material','Making, materials, heraldry and trade.'],['records','Records & lore','County documents and the research library.']].map(([route,title,text],i)=>`<a href="#${route}"><span class="number">0${i+1}</span><h3>${title}</h3><p>${text}</p></a>`).join('')}</div></section><section class="messenger-feature"><img src="assets/messenger-dispatch.png" alt="Illustrated messenger desk with crimson banners, a clerk, a saddled bat and gothic castle beyond"><div class="messenger-link"><button class="button gold" data-open-review>Messenger dispatch</button><p>Contributions and corrections for the County archive.</p></div></section>`;
  const placesWithTerrain=()=>places()+section('The keep’s hilltop',`<div class="wide-feature"><img src="assets/keep-terrain-reference.png" alt="User-supplied real-world terrain reference: a broad fortified summit above sheer rocky slopes"><div class="feature-copy"><p class="eyebrow">Terrain reference</p><h2>A broad,<br>flat summit.</h2><p>Your reference illustrates the hilltop scale and the relationship between the keep and its rocky base. Its real-world buildings, flag and vegetation are not Saravoia details.</p></div></div>`);
  const craftWithArt=()=>craft()+section('Decorative bat artwork',`<div class="wide-feature"><img src="assets/decorative-bat.png" alt="Decorative gold, crimson and black bat-inspired artwork with a central red jewel"><div class="feature-copy"><p class="eyebrow">Supplied visual reference</p><h2>Gold, crimson<br>and black.</h2><p>This ornamental artwork is retained as a design reference. The plain heraldic blazon remains a separate specification.</p></div></div>`);
  const pages={home:landing,county:countyHome,witchtown,places:placesWithTerrain,people,history,language,craft:craftWithArt,records,about};
  function books(kind='associated'){
    const list=document.querySelector('#book-list');if(!list)return;
    const bs=D.books.filter(b=>kind==='all'||(kind==='associated'?b.relevance.startsWith('Visindi'):b.relevance.startsWith('contextual')));
    list.innerHTML=bs.map((b,i)=>`<article class="book"><span class="book-index">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(b.title)}</h3><p>${esc(b.author==='[Unknown]'?'Author not supplied':b.author)}<br>${esc(b.id)} · catalogue entry</p></div><button class="text-button" data-book="${esc(b.id)}">Catalogue record</button></article>`).join('')||'<p class="empty">No catalogue entries in this view.</p>';
    document.querySelectorAll('[data-books]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.books===kind)));
  }
  function open(title,kicker,html){document.querySelector('#dialog-kicker').textContent=kicker;document.querySelector('#dialog-content').innerHTML=`<h2 id="dialog-title">${esc(title)}</h2>${html}`;dialog.showModal();}
  function showRecord(id){const r=all.find(r=>r.id===id);if(!r)return;const sourceNames=s=>D.sources.find(x=>x.id===s)?.name||s;
    open(r.name||r.title,'Archive record',`${r.summary?`<p>${esc(r.summary)}</p>`:''}${r.body?`<p>${esc(r.body)}</p>`:''}<h3>Source-supported note</h3><p>${esc(r.text)}</p><span class="source-label">${esc(r.layer)} · ${esc(r.status)}</span><details><summary>Source passages</summary>${r.refs.length?r.refs.map(e=>`<p class="source-meta">${esc(sourceNames(e.source))} · lines ${e.start}–${e.end}</p><blockquote>${esc(e.quote)}</blockquote>`).join(''):`<p>${r.secondary?'Available through the earlier conversation summary; primary passage not retrieved.':'The associated notice is retained in the research corpus; its private correspondence export is not reproduced on this site.'}</p>`}</details>`);
  }
  function render(){const route=location.hash.slice(1)||'home';if(route==='main')return;const page=pages[route]?route:'home';document.body.classList.toggle('landing-page',page==='home');main.innerHTML=pages[page]();document.title=`${page==='home'?'Saravoia':({county:'Saravoia',witchtown:'Witchtown',craft:'Craft & material',about:'About the archive'}[page]||page[0].toUpperCase()+page.slice(1))} · County Archive`;document.querySelectorAll('nav a').forEach(a=>{if(a.hash===`#${page}`||(page==='witchtown'&&a.hash==='#places'))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelector('#navigation').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');if(page==='records')books();window.scrollTo(0,0);}
  document.querySelector('.menu-toggle').addEventListener('click',e=>{const nav=document.querySelector('nav');const on=nav.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(on))});
  document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
  document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.record)showRecord(b.dataset.record);if(b.dataset.books)books(b.dataset.books);if(b.dataset.book){const book=D.books.find(x=>x.id===b.dataset.book);open(book.title,'Catalogue entry',`<p><strong>Visible author column:</strong> ${esc(book.author)}</p><p><strong>Object:</strong> ${esc(book.id)}</p><p>The full text is not captured in this catalogue entry. The visible title and author column remain as recorded, including truncation.</p><p class="source-meta">2026-10-02#14-40-11.txt · line ${book.line}</p>`)}if(b.hasAttribute('data-open-review'))open('Contributions & corrections','County archive','<p>The supplied handoff identifies Nezaya as the reviewer for Saravoia additions and corrections. The public submission wording is awaiting her confirmation.</p><p>New documentary material, corrected names and approved descriptions can be incorporated while retaining their sources.</p>')});
  window.addEventListener('hashchange',render);render();
})();
